'use strict';
/* The 10-hour map: Modules 12, 13 and 14 as four lines and 44 stops, one stop
   per syllabus topic, in syllabus order. Each stop is a short animated scene:
     nodes  [id, label, kind, column 0–2, row 0–2]
            kinds: atk attacker · usr person · doc content · db store · ai model
            or agent · tool tool or MCP server · sys service · soc defenders ·
            out outside destination · gate decision point
     beats  [from, to, tone, caption]   tones: ok · bad · data (sensitive data moving)
     impact what it cost
     fix    cut: the beat at which the control acts (it sits on that beat's
            destination); also: other boxes accepted as a right answer;
            name, stop (the caption when it acts), then: beats that follow
     miss   why a control anywhere else comes too late
     like   an everyday picture of the idea
     real   a documented case (adv: the Advanced-path case that walks it)
     ask    one question for the room
   Minutes are session time and add up to 600. Mechanism level only: no working payloads. */

const AT_LINES = [
  { id: 'rag', n: 1, name: 'RAG Security', mod: 'Module 12 · part 1', lab: 'm12', off: 0,
    lead: 'What the assistant reads decides what it says. Ten ways the knowledge behind an answer is poisoned, hijacked or leaked, and the two designs that hold.' },
  { id: 'mcp', n: 2, name: 'MCP Security', mod: 'Module 12 · part 2', lab: 'm12', off: 10,
    lead: 'Every MCP server is a door into the agent and out to your systems. Eight stops on who built the door, what it says, and what it can reach.' },
  { id: 'ship', n: 3, name: 'Secure Productization', mod: 'Module 13', lab: 'm13', off: 0,
    lead: 'From a working demo to a system you can stand behind: build, test, release, change and review, with a gate that asks for evidence each time.' },
  { id: 'soc', n: 4, name: 'SOC & Runtime Defense', mod: 'Module 14', lab: 'm14', off: 0,
    lead: 'It is live, so it will be attacked. See it, detect it, hunt it, and stop it at machine speed without stopping the business.' }
];

